INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, long_description_html, disclaimer, color_key, sort_order) VALUES ('everyday-spending', '6a8578266d00107b3bf3f481', 'Everyday Spending', 'Groceries, brands, leaving Amazon', 'Groceries, household goods, and retail — learn who actually owns the brands in your basket, then redirect that spending one aisle at a time.', NULL, NULL, 'c1', 1);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, long_description_html, disclaimer, color_key, sort_order) VALUES ('subscriptions', '6a8578266d00107b3bf3f483', 'Subscriptions', 'What''s quietly billing you monthly', 'Recurring digital revenue is what moves valuations. Audit every subscription you pay, cancel what you can, and move the rest to providers outside the target set.', NULL, NULL, 'c2', 2);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, long_description_html, disclaimer, color_key, sort_order) VALUES ('money-banking', '6a8578266d00107b3bf3f485', 'Money & Banking', 'Where your money sleeps at night', 'Your deposits are working capital that your bank lends and invests. Move them to member-owned institutions and pay on rails that don''t route a fee to a US network.', NULL, NULL, 'c3', 3);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, long_description_html, disclaimer, color_key, sort_order) VALUES ('investments', '6a8578266d00107b3bf3f487', 'Investments', 'You may own what you''re boycotting', 'You are probably already funding what you''re boycotting. Find out what your pension holds, then decide whether to move it, vote it, or organise around it.', NULL, 'Nothing in this category is financial advice. None of these actions names a security to buy — they are about finding out what you already own and who votes it. Decisions about your own money are yours, and worth taking to a regulated adviser.', 'c1', 4);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, long_description_html, disclaimer, color_key, sort_order) VALUES ('travel', '6a85786ec61c6c719566ef1c', 'Travel', 'The one with a public scoreboard', 'The only category with a public scoreboard — inbound tourism figures are published monthly. Skip the trip, take the train, and tell the operator why.', NULL, NULL, 'c2', 5);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, long_description_html, disclaimer, color_key, sort_order) VALUES ('institutions', '6a85786ec61c6c719566ef1e', 'Institutions', 'Highest impact, most effort', 'One organisation switching outweighs a thousand individual consumers. Your employer, council, union, club and congregation all sign contracts — and someone has to raise it.', NULL, NULL, 'c3', 6);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, long_description_html, disclaimer, color_key, sort_order) VALUES ('attention', '6a85786ec61c6c719566ef20', 'Attention', 'You''re the inventory. Stop supplying it.', 'Your attention, your posts and your data are the product these platforms sell. Withdraw the supply, block the ads, and fund the alternative with what you save.', NULL, NULL, 'c1', 7);
INSERT INTO categories (id, webflow_item_id, name, tagline, short_description, long_description_html, disclaimer, color_key, sort_order) VALUES ('data-rights', NULL, 'Data & Digital Rights', 'Rights you already have, unused', 'The GDPR and the DMA give you enforceable rights over data that has already been collected — deletion, access, objection, portability. Most people never use them. Each one costs an email and creates a record.', NULL, 'These actions describe rights in EU law and point to the published guidance of noyb and your national data protection authority. They are not legal advice, and this app does not draft your request for you — use the wording your DPA or noyb publishes.', 'c2', 8);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-cancel-amazon-prime', 'everyday-spending', 'Cancel Amazon Prime', 'One membership, six businesses you''re also funding.', 'Prime bundles retail, logistics, cloud, advertising and media into a single recurring charge. Cancelling is an account setting, not a boycott of every seller who happens to list there — and it stops the part of the bill that funds the bundle.', 25, 'once', NULL, NULL, 'global', '{}', '["subs_cancelled"]', '[]', 'Easy', '5 Minutes', 1, 1);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-delete-amazon-app', 'everyday-spending', 'Delete the Amazon app from your phone', 'Removes the two-tap path from idle thumb to checkout.', 'Most impulse orders come from the app, not the website. Deleting it doesn''t close your account — it just puts a browser and a login between you and the purchase, which is enough friction to break the habit.', 10, 'once', NULL, NULL, 'global', '{}', '[]', '[]', 'Easy', '5 Minutes', 1, 2);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-remove-saved-card', 'everyday-spending', 'Remove your saved card from one online retailer', 'One-click buying only works if the card is already there.', 'Stored payment details are the whole design of frictionless retail. Deleting the card from one retailer''s account means the next purchase is a decision rather than a reflex. Repeat it per retailer.', 10, 'repeatable', 1, NULL, 'global', '{}', '[]', '[]', 'Easy', '5 Minutes', 1, 3);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-independent-bookshop', 'everyday-spending', 'Buy your next book from an independent bookshop', 'Same book, and the margin stays in your town.', 'Independent bookshops order most titles within a couple of days, and many run their own online shops. The book costs about the same; the difference is which balance sheet it lands on.', 10, 'repeatable', 7, NULL, 'global', '{"default":["your nearest independent bookshop"],"de":["Genialokal","Buch7","Ocelot","your local Buchhandlung"],"nl":["Libris","Athenaeum"],"fr":["Place des Libraires","Librairies Indépendantes"],"uk":["Bookshop.org UK","Hive","your local high-street bookshop"],"es":["Todos tus Libros"],"us":["Bookshop.org","your local independent bookstore"]}', '["local_purchases","purchases_redirected"]', '[]', 'Easy', '10-30 Minutes', 0, 4);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-switch-cleaning-brand', 'everyday-spending', 'Switch one cleaning brand off P&G or Unilever', 'Detergent, dish soap, surface spray. Decided once, bought for years.', 'A handful of conglomerates own most of the cleaning aisle. Pick one product you rebuy on autopilot and change the default — the switch only has to be made once, but it repeats every time the cupboard empties.', 25, 'sustained', NULL, 90, 'global', '{"default":["an independent or cooperative household brand"],"de":["Frosch","Sonett","Sodasan","Ecover","Klar"],"at":["Frosch","Sonett","Klar"],"nl":["Ecover","Sonett"],"fr":["L''Arbre Vert","Rainett","Ecover"],"uk":["Ecover","Bio-D","Splosh"]}', '["purchases_redirected"]', '[]', 'Easy', '10-30 Minutes', 0, 5);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-switch-personal-care', 'everyday-spending', 'Switch your personal care brand', 'Shampoo, toothpaste, deodorant — same shelf, different owner.', 'Personal care is one of the most concentrated aisles in the shop. Changing one product you buy monthly redirects a small amount reliably, which is worth more than a large one-off.', 10, 'once', NULL, NULL, 'global', '{"default":["Weleda","Dr. Bronner''s","an independent care brand"],"de":["Weleda","Speick","Lavera","Alverde","Dr. Bronner''s"],"at":["Weleda","Speick","Lavera"],"fr":["Cattier","Melvita","Weleda"],"uk":["Faith in Nature","Weleda","Dr. Bronner''s"]}', '["purchases_redirected"]', '[]', 'Easy', '10-30 Minutes', 0, 6);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-cooperative-grocer', 'everyday-spending', 'Move your regular shop to a cooperative grocer', 'The weekly shop is the largest recurring number most people control.', 'Groceries go on autopilot to whichever shop is nearest or already in an app. Changing the default — to a co-op, a regional chain, a food cooperative — redirects a recurring amount rather than a single purchase. This one is worth checking in on, because defaults drift back.', 50, 'sustained', NULL, 90, 'global', '{}', '["purchases_redirected","local_purchases"]', '[]', 'Moderate', '10-30 Minutes', 0, 7);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-buy-refurbished', 'everyday-spending', 'Buy your next device refurbished instead of new', 'A phone that already exists doesn''t book a new unit sale.', 'Refurbished marketplaces sell graded, warrantied devices at a discount. The manufacturer records no new sale, and the device that would have been built isn''t. Warranties are typically 12–24 months.', 25, 'repeatable', 30, NULL, 'global', '{"default":["Back Market","Swappie","Rebuy"],"de":["Back Market","Rebuy","Refurbed","Swappie"],"at":["Refurbed","Back Market"],"fr":["Back Market","Recommerce"],"nl":["Back Market","Swappie"],"uk":["Back Market","Music Magpie","Swappie"]}', '["purchases_redirected"]', '[]', 'Easy', '10-30 Minutes', 0, 8);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-replace-soft-drink', 'everyday-spending', 'Replace one US soft drink brand for good', 'The most replaceable recurring purchase in the shop.', 'Soft drinks are bought by habit and brand recall, and nearly every European market has an independent cola or lemonade with a real following. This is the lowest-friction permanent swap on the list.', 10, 'sustained', NULL, 90, 'global', '{"default":["a local or independent soft drink brand"],"de":["Fritz-Kola","Afri-Cola","Bionade","Club-Mate"],"at":["Almdudler","Makava"],"nl":["Fritz-Kola","Rivella"],"fr":["Breizh Cola","Meuh Cola"],"uk":["Karma Cola","Fentimans"],"es":["Fritz-Kola","Casera"]}', '["purchases_redirected"]', '[]', 'Easy', '5 Minutes', 0, 9);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-buy-secondhand', 'everyday-spending', 'Buy it secondhand instead of new', 'Clothes, furniture, tools — the resale market is enormous and local.', 'Secondhand purchases move money between people rather than to a manufacturer. Most European countries have a dominant local marketplace that isn''t US-owned.', 10, 'repeatable', 7, NULL, 'global', '{"default":["Vinted","a local secondhand marketplace"],"de":["Vinted","Kleinanzeigen","Momox"],"at":["Willhaben","Vinted"],"fr":["Leboncoin","Vinted"],"nl":["Marktplaats","Vinted"],"es":["Wallapop","Vinted"],"uk":["Vinted","Gumtree"]}', '["purchases_redirected"]', '[]', 'Easy', '10-30 Minutes', 0, 10);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-skip-fast-food-chain', 'everyday-spending', 'Skip a US fast-food chain for a local place', 'Same lunch, and the money stays within a few streets.', 'Fast food is the most franchised category there is, and a franchise fee leaves the local economy on every order. The independent equivalent is usually the same price and closer.', 5, 'repeatable', 1, NULL, 'global', '{}', '["local_purchases","purchases_redirected"]', '[]', 'Easy', '5 Minutes', 0, 11);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-unsubscribe-marketing', 'everyday-spending', 'Unsubscribe from one retailer''s marketing emails', 'Cuts the prompt that generates the purchase.', 'Retail email exists to manufacture a purchase occasion you weren''t going to have. One unsubscribe link removes a recurring nudge permanently, and under GDPR the retailer has to honour it.', 5, 'repeatable', 1, NULL, 'global', '{}', '[]', '[]', 'Easy', '5 Minutes', 1, 12);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-local-market', 'everyday-spending', 'Shop at your local market this week', 'Producers, not distributors.', 'Market traders and producers keep a far larger share of what you hand over than a supermarket supply chain passes back. Once a week is a meaningful recurring redirect.', 5, 'repeatable', 7, NULL, 'global', '{}', '["local_purchases"]', '[]', 'Easy', '10-30 Minutes', 0, 13);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('everyday-cancel-warehouse-club', 'everyday-spending', 'Cancel a warehouse club membership', 'An annual fee for the privilege of spending more.', 'Warehouse memberships charge up front and then rely on bulk purchasing to justify themselves. Cancelling ends both the fee and the sunk-cost pull to keep shopping there.', 25, 'once', NULL, NULL, 'global', '{}', '["subs_cancelled"]', '[]', 'Easy', '10-30 Minutes', 0, 14);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-list-everything', 'subscriptions', 'List every subscription you''re paying for', 'One sitting, one list. Most people are wrong about the total.', 'Bank and card statements make this a fifteen-minute job: write down every recurring charge, what it is, and what it costs a year. You can''t cancel what you''ve forgotten you''re paying for, and the annual figure is usually the thing that prompts the rest of this category.', 10, 'once', NULL, NULL, 'global', '{}', '[]', '[]', 'Moderate', '10-30 Minutes', 0, 1);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-cancel-netflix', 'subscriptions', 'Cancel Netflix', 'A settings page and about ninety seconds.', 'Cancelling leaves your profile and viewing history intact until the end of the billing period, and you can restart any time — which is precisely why it''s an easy one to do now rather than deliberate over.', 25, 'once', NULL, NULL, 'global', '{}', '["subs_cancelled"]', '[]', 'Easy', '5 Minutes', 1, 2);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-cancel-disney', 'subscriptions', 'Cancel Disney+', 'One streaming subscription, cancelled or paused.', 'Disney+ is bundled aggressively and auto-renews annually in many markets, so it''s a common line item people don''t realise is still active.', 25, 'once', NULL, NULL, 'global', '{}', '["subs_cancelled"]', '[]', 'Easy', '5 Minutes', 0, 3);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-cancel-prime-video', 'subscriptions', 'Cancel Prime Video', 'Separate from Prime itself in most markets.', 'Prime Video is often billed as a standalone subscription or an add-on channel even for people who already cancelled Prime membership. Check both.', 25, 'once', NULL, NULL, 'global', '{}', '["subs_cancelled"]', '[]', 'Easy', '5 Minutes', 0, 4);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-cancel-apple-tv', 'subscriptions', 'Cancel Apple TV+', 'Frequently still running from a free trial attached to a device.', 'Apple TV+ is bundled with hardware purchases and with Apple One. It''s one of the most commonly forgotten active subscriptions because it never appears as its own card charge.', 25, 'once', NULL, NULL, 'global', '{}', '["subs_cancelled"]', '[]', 'Easy', '5 Minutes', 0, 5);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-cancel-max-paramount', 'subscriptions', 'Cancel Max or Paramount+', 'The third streaming service is usually the one you forgot.', 'Whichever of these you signed up for during a single series and never cancelled. Both are US studio-owned and both auto-renew.', 25, 'once', NULL, NULL, 'global', '{}', '["subs_cancelled"]', '[]', 'Easy', '5 Minutes', 0, 6);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-cancel-audible', 'subscriptions', 'Cancel Audible', 'Your library stays yours after you cancel.', 'Audible credits and purchased titles remain accessible after cancellation in most markets. Libraries in most European countries lend audiobooks free through apps, and several independent audiobook shops sell DRM-free.', 10, 'once', NULL, NULL, 'global', '{"default":["your public library''s audiobook app","Libro.fm","BookBeat"],"de":["Onleihe","Thalia","BookBeat"],"nl":["Bibliotheek app","Storytel"],"uk":["BorrowBox","Libro.fm"]}', '["subs_cancelled"]', '[]', 'Easy', '5 Minutes', 0, 7);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-public-broadcaster', 'subscriptions', 'Watch your public broadcaster instead', 'You already pay for it. Most people barely use it.', 'European public broadcasters have large free catalogues of drama, documentary and film, funded by a licence fee or tax you are paying whether you watch or not. Making one of them a default replaces streaming spend with something already bought.', 10, 'sustained', NULL, 90, 'eu', '{"default":["Arte"],"de":["ARD Mediathek","ZDF Mediathek","Arte"],"at":["ORF ON","Arte"],"fr":["france.tv","Arte"],"it":["RAI Play"],"es":["RTVE Play"],"nl":["NPO Start"],"se":["SVT Play"],"uk":["BBC iPlayer","Channel 4"]}', '["services_swapped_eu"]', '[]', 'Easy', '5 Minutes', 0, 8);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-european-streaming', 'subscriptions', 'Subscribe to a European streaming service', 'If you''re going to pay for one, pay a European one.', 'Replacing rather than merely cancelling keeps the habit and moves the money. European services tend to carry deeper European and arthouse catalogues than the US majors do.', 10, 'once', NULL, NULL, 'eu', '{"default":["MUBI","Filmin","Viaplay"],"de":["Joyn","MUBI","WOW"],"es":["Filmin","MUBI"],"nl":["Videoland","MUBI"],"se":["Viaplay","SF Anytime"]}', '["services_swapped_eu"]', '[]', 'Easy', '10-30 Minutes', 0, 9);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-move-cloud-storage', 'subscriptions', 'Move your cloud storage off Google, Apple or Microsoft', 'Photos and files, migrated to a European provider.', 'The migration is the only real friction — most providers offer a direct import or a desktop sync client that handles it overnight. Do it once and the monthly charge simply moves. Storage is also the subscription most likely to be silently upgraded as you fill it.', 50, 'once', NULL, NULL, 'global', '{"default":["Proton Drive","pCloud","Nextcloud","Filen"],"de":["Hetzner Storage Share","Nextcloud","Your Secure Cloud"],"ch":["Infomaniak kDrive","pCloud","Proton Drive"],"fr":["Infomaniak kDrive","OVHcloud"],"no":["Jottacloud"]}', '["services_swapped_eu","accounts_moved"]', '[{"label":"European Alternatives","url":"https://european-alternatives.eu/"}]', 'Moderate', '1-2 Hours', 0, 10);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-move-email', 'subscriptions', 'Move your email off Gmail or Outlook', 'The highest-leverage switch on the list, and the most work.', 'Your mailbox is the recovery address for every other account you own, which is exactly why moving it matters and why it takes an afternoon. Most providers import your existing mail and contacts automatically, and can forward from the old address indefinitely while you update logins.', 75, 'once', NULL, NULL, 'global', '{"default":["Proton Mail","Tuta","Mailbox.org","Infomaniak"],"de":["Mailbox.org","Posteo","Tuta"],"ch":["Proton Mail","Infomaniak"],"fr":["Infomaniak","Proton Mail"]}', '["services_swapped_eu","accounts_moved"]', '[{"label":"European Alternatives","url":"https://european-alternatives.eu/"}]', 'Advanced', '1-2 Hours', 0, 11);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-replace-office-suite', 'subscriptions', 'Replace your US office suite', 'Documents, spreadsheets, slides — without the subscription.', 'For most personal use the free European and open-source suites are a straight replacement and read Microsoft formats without conversion. If you collaborate, the hosted options handle shared editing too.', 50, 'once', NULL, NULL, 'global', '{"default":["LibreOffice","OnlyOffice","CryptPad","Nextcloud Office"]}', '["services_swapped_eu","subs_cancelled"]', '[]', 'Moderate', '1-2 Hours', 0, 12);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('subs-european-vpn', 'subscriptions', 'Switch to a European VPN', 'A VPN sees everything. Jurisdiction matters more here than anywhere.', 'A VPN provider can see the traffic your ISP can''t, so where it is incorporated and what it is legally obliged to hand over is the whole product. Prefer audited, no-log providers under European jurisdiction.', 25, 'once', NULL, NULL, 'global', '{"default":["Proton VPN","Mullvad","IVPN"]}', '["services_swapped_eu"]', '[]', 'Easy', '10-30 Minutes', 0, 13);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-open-ethical-account', 'money-banking', 'Open an account at a cooperative or ethical bank', 'Opening it is the fast part. Deciding to is the slow part.', 'Cooperative and ethical banks are member-owned or mission-constrained, and most publish what they will and won''t lend to. Opening an account is usually online and takes under half an hour — you don''t have to move anything into it on day one.', 50, 'once', NULL, NULL, 'global', '{"default":["a cooperative or ethical bank"],"de":["GLS Bank","Umweltbank","EthikBank","Triodos","your local Volksbank or Sparkasse"],"at":["Bank für Gemeinwohl","Raiffeisen"],"nl":["Triodos","ASN Bank","Rabobank"],"fr":["Crédit Coopératif","La Nef","Crédit Mutuel"],"it":["Banca Etica"],"es":["Fiare Banca Etica","Caja Laboral"],"se":["Ekobanken"],"dk":["Merkur Andelskasse"],"no":["Cultura Bank"],"uk":["Nationwide","Co-operative Bank","Triodos UK","your local credit union"],"us":["a local credit union"]}', '["accounts_moved"]', '[{"label":"BankTrack","url":"https://www.banktrack.org/"}]', 'Moderate', '10-30 Minutes', 0, 1);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-move-primary-account', 'money-banking', 'Move your primary current account', 'Your everyday balance is working capital your bank lends out.', 'This is the one that actually moves money rather than opening an option. Salary, direct debits and standing orders all have to follow — most European countries mandate a switching service that does this within days and forwards anything missed. Worth checking in on, because the old account tends to linger.', 100, 'sustained', NULL, 90, 'global', '{}', '["accounts_moved"]', '[{"label":"BankTrack","url":"https://www.banktrack.org/"}]', 'Advanced', '1-2 Hours', 0, 2);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-move-savings', 'money-banking', 'Move your savings to an ethical bank', 'Savings are the easiest balance to move — nothing is attached to them.', 'Unlike a current account, savings have no direct debits or salary to redirect, so moving them is a transfer and nothing else. It''s the largest amount most people can redirect in a single afternoon.', 75, 'once', NULL, NULL, 'global', '{}', '["accounts_moved"]', '[]', 'Moderate', '10-30 Minutes', 0, 3);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-leave-detention-fossil-financier', 'money-banking', 'Move your money out of a detention or fossil financier', 'Check the lists first, then decide whether your bank is on one.', 'BankTrack and Urgewald publish researched, sourced lists of which banks finance fossil expansion, arms and private detention. Look your bank up. If it''s there, moving is a concrete response — and telling them why is the next action.', 75, 'once', NULL, NULL, 'global', '{}', '["accounts_moved"]', '[{"label":"BankTrack","url":"https://www.banktrack.org/"},{"label":"Urgewald","url":"https://www.urgewald.org/en"},{"label":"Prison Free Funds","url":"https://prisonfreefunds.org"}]', 'Moderate', '10-30 Minutes', 0, 4);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-non-us-card-issuer', 'money-banking', 'Switch your card to a non-US-linked issuer', 'Every card transaction routes a fee to a network.', 'Visa and Mastercard take an interchange fee on essentially every card payment in Europe. A domestic debit scheme or a card issued on a European network keeps that fee inside the local system.', 50, 'once', NULL, NULL, 'global', '{}', '["non_us_payments"]', '[]', 'Moderate', '10-30 Minutes', 0, 5);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-domestic-payment-scheme', 'money-banking', 'Pay by Wero, girocard, Bizum or your domestic scheme', 'Most European countries have their own rails. Use them.', 'Domestic account-to-account schemes settle directly between banks and don''t route a fee through a US card network. Making one your default for everyday payments is a per-transaction redirect that adds up faster than any single switch.', 50, 'sustained', NULL, 90, 'eu', '{"default":["your domestic account-to-account scheme"],"de":["Wero","girocard"],"fr":["Wero","Cartes Bancaires"],"be":["Wero","Bancontact"],"nl":["iDEAL","Wero"],"es":["Bizum"],"pt":["MB Way"],"it":["Bancomat Pay"],"pl":["BLIK"],"se":["Swish"],"dk":["MobilePay"],"fi":["MobilePay"]}', '["non_us_payments"]', '[]', 'Easy', '10-30 Minutes', 0, 6);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-sepa-direct-transfer', 'money-banking', 'Move one recurring bill to SEPA direct transfer', 'Same bill, no card network in the middle.', 'Most utilities, insurers and telecoms accept SEPA direct debit or standing order as an alternative to paying by card. Switching one recurring bill removes a card fee permanently.', 25, 'once', NULL, NULL, 'eu', '{}', '["non_us_payments"]', '[]', 'Easy', '10-30 Minutes', 0, 7);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-stop-paypal-recurring', 'money-banking', 'Stop using PayPal for one recurring payment', 'An extra US intermediary on a payment that doesn''t need one.', 'PayPal sits between you and the merchant and takes a cut of each transaction. Most merchants accept SEPA direct debit or a domestic scheme instead — changing the payment method on one recurring charge takes a couple of minutes.', 25, 'once', NULL, NULL, 'global', '{}', '["non_us_payments"]', '[]', 'Easy', '5 Minutes', 0, 8);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-remove-apple-google-pay', 'money-banking', 'Remove Apple Pay or Google Pay as your default', 'A wallet layer on top of the card fee you''re already paying.', 'Tokenised wallets add a platform fee on top of card interchange and give the platform a view of your purchase history. Removing the default takes one settings change; your physical card and domestic scheme still work.', 10, 'once', NULL, NULL, 'global', '{}', '["non_us_payments"]', '[]', 'Easy', '5 Minutes', 0, 9);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-cancel-us-credit-card', 'money-banking', 'Cancel a US-issued credit card', 'Close the line, not just the habit.', 'An unused card still represents a lending relationship and often an annual fee. Clear the balance, redirect anything recurring on it first, then close it in writing so there''s a record.', 25, 'once', NULL, NULL, 'global', '{}', '["accounts_closed"]', '[]', 'Moderate', '10-30 Minutes', 0, 10);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-pay-cash-week', 'money-banking', 'Pay cash for a week', 'No interchange, no data, no intermediary.', 'Cash is the only payment method that routes nothing to anyone. A week of it also makes visible how many small transactions were going through a card network without you noticing.', 10, 'repeatable', 7, NULL, 'global', '{}', '["non_us_payments"]', '[]', 'Easy', 'Ongoing', 0, 11);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-tell-bank-why', 'money-banking', 'Tell your bank why you left, in writing', 'A closed account is a number. A letter is a reason.', 'Banks track attrition but not motive unless you supply it. A short written note at closure — naming what you objected to — puts a reason on the file that retention teams actually read and report upward.', 25, 'once', NULL, NULL, 'global', '{}', '["comments_filed"]', '[]', 'Easy', '10-30 Minutes', 0, 12);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('banking-ask-club-congregation', 'money-banking', 'Ask your club or congregation which bank it uses', 'Organisations hold larger balances than any of their members.', 'A sports club, choir, Verein or congregation has a treasurer, a bank account and usually nobody who has ever asked about it. The question alone often starts the first review that account has had in a decade.', 25, 'once', NULL, NULL, 'global', '{}', '["institutional_actions"]', '[]', 'Easy', '10-30 Minutes', 0, 13);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('invest-get-pension-holdings', 'investments', 'Get your pension''s holdings list', 'You may already own what you''re boycotting.', 'Workplace pensions are handed to you with a default fund nobody explains. Ask your provider or scheme administrator in writing for the full holdings list of the fund you are in — most are obliged to supply it, and many publish it already. This single request replaces asking your employer, your provider and your scheme separately: one email, addressed to whoever administers the plan, gets the document all three would point you to.', 25, 'once', NULL, NULL, 'global', '{}', '["investment_actions"]', '[{"label":"As You Sow","url":"https://www.asyousow.org/"},{"label":"ShareAction","url":"https://shareaction.org/"}]', 'Moderate', '10-30 Minutes', 0, 1);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('invest-find-plan-administrator', 'investments', 'Find out who administers your workplace plan', 'You can''t ask the right question until you know who to send it to.', 'The company you work for, the scheme trustee and the asset manager are three different organisations, and only one of them can change what the fund holds. Your payslip or HR portal names the provider; that''s the address for everything else in this category.', 10, 'once', NULL, NULL, 'global', '{}', '["investment_actions"]', '[]', 'Easy', '10-30 Minutes', 0, 2);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('invest-move-to-european-broker', 'investments', 'Move a self-managed account to a European broker', 'Same holdings, custodied in Europe.', 'Most European brokers accept in-kind transfers, so you move the positions rather than selling them — which usually avoids triggering a taxable disposal. Check the transfer-out fee at your current broker; many European brokers reimburse it.', 75, 'once', NULL, NULL, 'eu', '{"default":["Trade Republic","Scalable Capital","DEGIRO","Nordnet"],"de":["Trade Republic","Scalable Capital","Comdirect"],"nl":["DEGIRO","Bux"],"be":["Bolero","DEGIRO"],"se":["Nordnet","Avanza"],"fr":["Boursorama","DEGIRO"]}', '["investment_actions","accounts_moved"]', '[]', 'Advanced', '1-2 Hours', 0, 3);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('invest-switch-to-screened-fund', 'investments', 'Switch one fund to a screened alternative', 'Most plans offer one. Almost nobody changes the default.', 'Workplace schemes typically include at least one screened or sustainable fund alongside the default, and switching is a form rather than a transaction. Read what the screen actually excludes before you move — the labels vary far more than the marketing suggests.', 75, 'once', NULL, NULL, 'global', '{"default":["a screened or exclusion-based fund in your plan"],"de":["Triodos","GLS","Ökoworld"],"nl":["Triodos","ASN"]}', '["investment_actions"]', '[]', 'Advanced', '1-2 Hours', 0, 4);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('invest-us-etf-to-ucits', 'investments', 'Move a US-domiciled ETF into a UCITS equivalent', 'Same index, European domicile, usually better tax treatment.', 'For most European residents a UCITS version of the same index is the more sensible domicile anyway — US-domiciled funds can carry withholding tax and estate-tax exposure that the UCITS equivalent doesn''t. This is a like-for-like change of wrapper, not a change of strategy.', 50, 'once', NULL, NULL, 'eu', '{}', '["investment_actions"]', '[]', 'Advanced', '1-2 Hours', 0, 5);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('invest-divest-named-holding', 'investments', 'Divest one named holding', 'One position, identified and exited deliberately.', 'Pick a single holding you can name and justify exiting, and exit it. This is the action that turns a holdings list into a decision — and unlike a whole-portfolio move it can be done in an afternoon.', 50, 'once', NULL, NULL, 'global', '{}', '["investment_actions"]', '[]', 'Moderate', '10-30 Minutes', 0, 6);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('invest-vote-proxy', 'investments', 'Vote your proxy', 'You get a ballot every year. Most go straight in the bin.', 'If you hold shares directly, your broker sends you voting materials before each AGM. Unvoted shares often end up supporting management by default. Voting takes minutes and is the cheapest influence a small holder has.', 50, 'repeatable', 30, NULL, 'global', '{}', '["investment_actions"]', '[{"label":"ShareAction","url":"https://shareaction.org/"}]', 'Moderate', '10-30 Minutes', 0, 7);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('invest-back-shareholder-resolution', 'investments', 'Back a shareholder resolution', 'Filed resolutions need supporting votes to survive.', 'Campaign groups file resolutions on climate, tax and labour every AGM season and publish which ones need retail support. Backing one is a specific vote on a specific question rather than a general protest.', 25, 'repeatable', 30, NULL, 'global', '{}', '["investment_actions"]', '[{"label":"ShareAction","url":"https://shareaction.org/"},{"label":"As You Sow","url":"https://www.asyousow.org/"}]', 'Moderate', '10-30 Minutes', 0, 8);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('invest-ask-for-exclusion-list', 'investments', 'Ask your provider to publish its exclusion list', 'Plenty of funds have one. Far fewer publish it.', 'A fund that markets itself as sustainable should be able to tell you what it excludes and at what threshold. Asking in writing costs nothing, and providers count these requests when deciding what to disclose.', 25, 'once', NULL, NULL, 'global', '{}', '["investment_actions","comments_filed"]', '[]', 'Easy', '10-30 Minutes', 0, 9);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('invest-attend-member-meeting', 'investments', 'Attend your pension scheme''s member meeting', 'Usually sparsely attended, and questions get minuted.', 'Schemes hold member meetings that hardly anyone goes to, which means a single prepared question lands with unusual weight and enters the record. Ask what the scheme holds and how it votes.', 25, 'repeatable', 90, NULL, 'global', '{}', '["investment_actions","institutional_actions"]', '[]', 'Moderate', '1-2 Hours', 0, 10);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('invest-works-council-plan-provider', 'investments', 'Ask your works council to raise the plan provider', 'A works council can put this on an agenda. You can''t.', 'In much of Europe the works council or staff committee has formal consultation rights over occupational pension arrangements. Raising the provider through them turns an individual complaint into an agenda item with a required response.', 25, 'once', NULL, NULL, 'eu', '{}', '["investment_actions","institutional_actions"]', '[]', 'Moderate', '10-30 Minutes', 0, 11);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-redirect-us-trip', 'travel', 'Cancel or redirect a US trip, and say why', 'Inbound tourism is counted and published monthly.', 'Travel is the one category with a public scoreboard: arrivals and tourism receipts are reported as national statistics. Cancelling or redirecting a trip registers there — and telling the airline, hotel or tourist board why turns a data point into a stated reason.', 50, 'once', NULL, NULL, 'global', '{}', '["comments_filed"]', '[]', 'Moderate', '10-30 Minutes', 0, 1);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-train-over-short-haul', 'travel', 'Take the train instead of a short-haul flight', 'Under about five hours, the train usually wins door to door.', 'Once you count airport transfer, security and boarding, most European city pairs under 700km are faster by rail. Booking direct with the national operator also avoids a platform fee.', 25, 'repeatable', 1, NULL, 'eu', '{"default":["DB","SNCF","Trenitalia","ÖBB","Trainline"],"de":["DB","ÖBB"],"fr":["SNCF Connect","Trainline"],"it":["Trenitalia","Italo"],"es":["Renfe"],"at":["ÖBB"],"nl":["NS International"]}', '["train_over_flight"]', '[]', 'Easy', '10-30 Minutes', 0, 2);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-night-train', 'travel', 'Book a night train', 'Replaces a flight and a hotel night at once.', 'Europe''s sleeper network has expanded considerably — Nightjet, European Sleeper and Snälltåget now connect most of the continent. Booking one removes a flight from the count and a hotel night from the bill.', 25, 'repeatable', 7, NULL, 'eu', '{"default":["ÖBB Nightjet","European Sleeper","Snälltåget"]}', '["train_over_flight"]', '[]', 'Easy', '10-30 Minutes', 0, 3);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-interrail-pass', 'travel', 'Get an Interrail or Eurail pass', 'Prepays a season of travel onto European rail.', 'A pass commits a block of travel spending to European rail operators up front, and tends to change how you plan trips for the rest of the year — flights stop being the default option because the rail is already paid for.', 25, 'once', NULL, NULL, 'eu', '{"default":["Interrail","Eurail"]}', '["train_over_flight"]', '[]', 'Easy', '10-30 Minutes', 0, 4);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-holiday-in-europe', 'travel', 'Holiday in Europe this year', 'The whole trip, not one leg of it.', 'Choosing a European destination for your main holiday moves flights, accommodation, food and local spending together. It''s the single largest discretionary redirect most households make in a year, which is why it''s worth checking in on rather than logging once.', 25, 'sustained', NULL, 90, 'eu', '{}', '[]', '[]', 'Moderate', 'Varies', 0, 5);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-european-carrier', 'travel', 'Fly a European carrier instead of a US one', 'When you do fly, the airline is still a choice.', 'On transatlantic and intra-European routes there is nearly always a European operator on the same city pair, often codesharing the identical flight. Booking the European metal keeps the fare with the European carrier.', 10, 'repeatable', 7, NULL, 'global', '{}', '[]', '[]', 'Easy', '10-30 Minutes', 0, 6);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-book-hotel-direct', 'travel', 'Book your hotel direct instead of through a platform', 'Booking.com is US-owned. Most people assume otherwise.', 'Booking.com reads as European because of the Amsterdam office and the .com trading name, but it is owned by Booking Holdings, a US company headquartered in Connecticut — as are Kayak, Priceline, Agoda and OpenTable. Booking direct with the hotel avoids a commission that commonly runs 15–20% of the room rate, and hotels will usually match or beat the platform price if you ask.', 10, 'repeatable', 7, NULL, 'global', '{}', '["purchases_redirected"]', '[]', 'Easy', '10-30 Minutes', 0, 7);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-skip-airbnb', 'travel', 'Skip Airbnb for a local guesthouse or Fairbnb', 'A pension, a guesthouse, or a cooperative platform.', 'Independent guesthouses and small hotels keep the whole rate, and cooperative platforms return a share of their commission to local projects. In most European cities this is also the cheaper option once cleaning and service fees are counted.', 10, 'repeatable', 7, NULL, 'global', '{"default":["Fairbnb.coop","a local guesthouse or pension"]}', '["purchases_redirected","local_purchases"]', '[]', 'Easy', '10-30 Minutes', 0, 8);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-european-car-rental', 'travel', 'Rent from a European car company', 'Same car class, European operator.', 'Hertz, Avis, Budget and Enterprise are US groups; Sixt and Europcar are European and operate the same airport and city desks at comparable rates.', 10, 'repeatable', 7, NULL, 'eu', '{"default":["Sixt","Europcar"]}', '["purchases_redirected"]', '[]', 'Easy', '10-30 Minutes', 0, 9);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-national-tourist-board', 'travel', 'Use a national tourist board instead of a US platform', 'Better information, no commission, no tracking.', 'National and regional tourist boards publish the same accommodation, transport and event listings the platforms aggregate, and usually link straight to the operator. Planning from there avoids feeding a booking platform''s ranking data.', 10, 'repeatable', 7, NULL, 'global', '{}', '[]', '[]', 'Easy', '10-30 Minutes', 0, 10);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-take-the-coach', 'travel', 'Take the coach instead', 'The cheapest way to not take a flight.', 'Long-distance coaches cover routes rail doesn''t and undercut both rail and air on price. For a short hop it''s the lowest-cost substitution available.', 5, 'repeatable', 1, NULL, 'eu', '{"default":["Flixbus","ALSA","Eurolines"]}', '["train_over_flight"]', '[]', 'Easy', '10-30 Minutes', 0, 11);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('travel-tell-operator-why', 'travel', 'Tell an operator why you changed your booking', 'Cancellations are counted. Reasons are not, unless you give one.', 'Airlines, hotels and booking platforms all run cancellation surveys and none of them infer motive. A sentence in the feedback box or a short email to customer relations puts your reason into a dataset someone reports on.', 10, 'once', NULL, NULL, 'global', '{}', '["comments_filed"]', '[]', 'Easy', '5 Minutes', 0, 12);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-ask-employer-cloud-provider', 'institutions', 'Ask your employer who its cloud provider is', 'One email to IT. The answer is rarely a secret.', 'Most organisations run on one of three US hyperscalers and have never been asked about it by an employee. The question is legitimate, cheap, and it''s the opening move for every other action in this category.', 25, 'once', NULL, NULL, 'global', '{}', '["institutional_actions"]', '[{"label":"EuroStack","url":"https://eurostack.eu/"}]', 'Easy', '10-30 Minutes', 0, 1);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-propose-procurement-change', 'institutions', 'Propose one procurement change in writing', 'One organisation switching outweighs a thousand consumers.', 'A written proposal — one named system, one named alternative, a cost comparison and a migration sketch — is the artefact that actually moves a procurement decision. It has to be written down to be considered, and almost nobody writes it down.', 75, 'once', NULL, NULL, 'global', '{}', '["institutional_actions"]', '[{"label":"EuroStack","url":"https://eurostack.eu/"},{"label":"European Alternatives","url":"https://european-alternatives.eu/"}]', 'Advanced', '1-2 Hours', 0, 2);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-raise-vendor-works-council', 'institutions', 'Raise a vendor at your works council or union', 'A works council has consultation rights you don''t.', 'Works councils and unions can require a response on decisions that affect working conditions, including monitoring software and platform contracts. Raising a vendor there converts an individual objection into a formal process with a timetable.', 50, 'once', NULL, NULL, 'eu', '{}', '["institutional_actions"]', '[]', 'Moderate', '10-30 Minutes', 0, 3);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-ask-school-software', 'institutions', 'Ask your child''s school which software it runs on', 'Schools hand children a platform account for a decade.', 'Most schools have standardised on a US education suite without a data protection assessment a parent has ever seen. Several European DPAs have ruled on exactly this. Asking as a parent is a question the school is obliged to engage with.', 25, 'once', NULL, NULL, 'global', '{}', '["institutional_actions"]', '[]', 'Easy', '10-30 Minutes', 0, 4);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-public-comment-contract', 'institutions', 'Submit a public comment on a public contract', 'Consultations get a handful of responses. Yours is read.', 'Councils, agencies and public bodies run formal consultations on procurement and technology decisions, and typically receive very few responses — so each one is read and logged. Find an open consultation on a contract in your area and file a comment on the record. This covers writing to your local authority as well: the consultation is the channel where it counts.', 50, 'repeatable', 14, NULL, 'global', '{}', '["comments_filed","institutional_actions"]', '[]', 'Moderate', '1-2 Hours', 0, 5);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-look-up-contract-ted', 'institutions', 'Look up a contract on TED or your procurement portal', 'Public contracts above threshold are published. Anyone can read them.', 'TED (Tenders Electronic Daily) publishes EU public procurement notices, and every member state runs a national portal. Looking up what your council or university has signed, and with whom, is the research that makes a public comment specific rather than general.', 10, 'once', NULL, NULL, 'eu', '{}', '["institutional_actions"]', '[{"label":"TED — Tenders Electronic Daily","url":"https://ted.europa.eu/"}]', 'Moderate', '10-30 Minutes', 0, 6);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-attend-council-meeting', 'institutions', 'Attend a council or shareholder meeting', 'Public bodies have public meetings with a question slot.', 'Council meetings, university senates and AGMs all reserve time for questions from members or the public, and those questions are minuted. Turning up with one specific, answerable question is disproportionately effective because so few people do.', 25, 'repeatable', 30, NULL, 'global', '{}', '["institutional_actions"]', '[]', 'Moderate', '1-2 Hours', 0, 7);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-sign-eci', 'institutions', 'Sign a European Citizens'' Initiative', 'A million signatures obliges the Commission to respond.', 'The ECI is the EU''s formal citizen-initiative instrument: reach one million verified signatures across at least seven member states and the Commission must meet the organisers and state publicly what it will do. Signing is verified against your ID number, so each signature genuinely counts once.', 10, 'repeatable', 30, NULL, 'eu', '{}', '["comments_filed"]', '[{"label":"European Citizens'' Initiative","url":"https://citizens-initiative.europa.eu/"}]', 'Easy', '10-30 Minutes', 0, 8);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-write-mep-digital-sovereignty', 'institutions', 'Write to your MEP about digital sovereignty', 'MEPs receive far less constituent mail than national politicians.', 'Individual, non-form letters are weighted heavily by parliamentary offices precisely because they''re rare. Name a specific file — procurement rules, cloud certification, DMA enforcement — rather than writing generally.', 25, 'repeatable', 30, NULL, 'eu', '{}', '["comments_filed"]', '[{"label":"Find your MEP","url":"https://www.europarl.europa.eu/meps/en/home"}]', 'Moderate', '10-30 Minutes', 0, 9);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-petition-european-parliament', 'institutions', 'Petition the European Parliament', 'A right of every EU resident, and it gets a formal reply.', 'Anyone residing in the EU can petition Parliament on a matter within EU competence. The Committee on Petitions must consider it and respond — an individual can put an item in front of a parliamentary committee without any organisation behind them.', 25, 'repeatable', 30, NULL, 'eu', '{}', '["comments_filed"]', '[{"label":"Parliament petitions portal","url":"https://www.europarl.europa.eu/petitions/en/home"}]', 'Moderate', '1-2 Hours', 0, 10);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-vote-local-election-eu-resident', 'institutions', 'Vote in your local election as an EU resident', 'You can vote where you live, not only where you''re from.', 'EU citizens have the right to vote and stand in municipal elections in their country of residence, and in European Parliament elections. In most member states you have to register on a specific roll first, often months ahead — which is the step people miss.', 50, 'once', NULL, NULL, 'eu', '{}', '["institutional_actions"]', '[]', 'Moderate', '10-30 Minutes', 0, 11);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-register-to-vote', 'institutions', 'Register to vote, or confirm you''re registered', 'Registrations get purged. Check rather than assume.', 'Voter rolls are periodically cleaned, and a move, a name change or simply not voting in a cycle can remove you. Confirming takes a couple of minutes online in most states.', 25, 'once', NULL, NULL, 'us', '{}', '["institutional_actions"]', '[]', 'Easy', '10-30 Minutes', 0, 12);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('inst-ask-club-contracts', 'institutions', 'Ask your Verein or club about its contracts', 'Clubs sign for software, banking and insurance too.', 'A Verein, sports club or association has a committee, a budget and contracts nobody reviews between AGMs. Members can ask, and the AGM is the place where the answer has to be given.', 25, 'once', NULL, NULL, 'eu', '{}', '["institutional_actions"]', '[]', 'Easy', '10-30 Minutes', 0, 13);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-install-ublock-origin', 'attention', 'Install uBlock Origin', 'The single highest-leverage thing you can install in two minutes.', 'Blocking ads and trackers removes you from the auction that funds surveillance advertising — every blocked request is an impression nobody gets paid for. It''s free, open source, and the reason Chrome''s extension changes made it worth switching browsers.', 10, 'once', NULL, NULL, 'global', '{"default":["uBlock Origin"]}', '["services_swapped_eu"]', '[{"label":"uBlock Origin","url":"https://ublockorigin.com/"}]', 'Easy', '5 Minutes', 1, 1);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-delete-x-account', 'attention', 'Delete your X account', 'Not deactivate. Delete.', 'Export your archive first if you want it — the download takes a day or so to prepare. Deletion is final after the grace period, which is the point: a deactivated account is still counted as a user.', 50, 'once', NULL, NULL, 'global', '{}', '["accounts_closed"]', '[]', 'Easy', '10-30 Minutes', 0, 2);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-deactivate-meta', 'attention', 'Deactivate Instagram or Facebook', 'Start with deactivation if deletion feels too final.', 'Deactivation stops the feed and the ad impressions while leaving your data recoverable, which makes it an easier first step than deletion. Treat it as sustained rather than done — reactivation is one login away, which is exactly how it''s designed.', 50, 'sustained', NULL, 90, 'global', '{}', '[]', '[]', 'Easy', '10-30 Minutes', 0, 3);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-move-group-chat', 'attention', 'Move a group chat off WhatsApp', 'The hardest switch, because it needs other people.', 'Messaging is a network effect, so moving one group is worth more than moving yourself. Pick a group with a reason to care, propose one alternative rather than three, and move the group rather than asking people to install something speculatively.', 50, 'once', NULL, NULL, 'global', '{"default":["Signal","Element/Matrix","Wire"],"ch":["Threema","Signal"],"de":["Signal","Threema","Element/Matrix"]}', '["services_swapped_eu"]', '[]', 'Moderate', '10-30 Minutes', 0, 4);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-switch-search-engine', 'attention', 'Switch your default search engine', 'One settings change, applied to every search after it.', 'Search is the highest-frequency interaction most people have with a US platform. Changing the browser default redirects all of it at once, and the European options run their own indexes or pay into non-US ones.', 10, 'once', NULL, NULL, 'global', '{"default":["Ecosia","Qwant","Startpage","Mojeek"]}', '["services_swapped_eu"]', '[]', 'Easy', '5 Minutes', 1, 5);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-switch-browser', 'attention', 'Switch your browser off Chrome', 'The browser decides what the ad blocker is allowed to do.', 'Chrome''s extension platform restricts what content blockers can do, and Chrome reports to the company that sells the ads. Firefox and its derivatives keep full blocking capability. Bookmarks, passwords and history all import in one step.', 25, 'once', NULL, NULL, 'global', '{"default":["Firefox","Vivaldi","LibreWolf"]}', '["services_swapped_eu"]', '[]', 'Easy', '10-30 Minutes', 0, 6);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-switch-maps', 'attention', 'Switch your maps app', 'Location history is the most sensitive log you generate.', 'Maps apps record everywhere you go by default. The open alternatives work offline from downloaded OpenStreetMap data, which is both more private and more useful with no signal.', 10, 'once', NULL, NULL, 'global', '{"default":["Organic Maps","OsmAnd","Magic Earth","HERE WeGo"]}', '["services_swapped_eu"]', '[]', 'Easy', '5 Minutes', 0, 7);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-join-mastodon', 'attention', 'Join Mastodon or a European platform', 'Leaving is easier when there''s somewhere to go.', 'Withdrawal alone tends not to stick — most people who delete an account come back because nothing replaced it. Joining a federated or European platform first makes the deletion durable.', 25, 'once', NULL, NULL, 'global', '{"default":["Mastodon","PeerTube","Pixelfed"]}', '["services_swapped_eu"]', '[]', 'Easy', '10-30 Minutes', 0, 8);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-chronological-feed', 'attention', 'Switch to a chronological feed', 'Turns off the ranking that optimises for time spent.', 'Most platforms still offer a chronological option, buried, because regulators required it. It ends the recommendation loop while you''re still using the service — a useful step if you''re not ready to leave.', 10, 'once', NULL, NULL, 'global', '{}', '[]', '[]', 'Easy', '5 Minutes', 1, 9);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-turn-off-ad-personalisation', 'attention', 'Turn off ad personalisation on one platform', 'Devalues your profile without deleting the account.', 'Ad personalisation settings exist on every major platform and are switched on by default. Turning them off lowers what your attention sells for, and in the EU you can require it under the GDPR rather than merely request it.', 10, 'once', NULL, NULL, 'global', '{}', '[]', '[]', 'Easy', '5 Minutes', 1, 10);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-subscribe-local-newspaper', 'attention', 'Subscribe directly to a local newspaper', 'Replaces an algorithmic feed with something someone edited.', 'Local reporting is what collapsed when advertising moved to the platforms, and a direct subscription is the only funding model that reaches the newsroom intact. It''s the constructive half of leaving a feed behind.', 25, 'sustained', NULL, 90, 'global', '{}', '["local_purchases"]', '[]', 'Easy', '10-30 Minutes', 0, 11);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('attn-consent-o-matic', 'attention', 'Install Consent-O-Matic and reject by default', 'Answers every cookie banner the way you would, automatically.', 'Built by researchers at Aarhus University, it fills in consent dialogs according to settings you choose once — rejecting non-essential processing on every site without the dark-pattern click maze. Refusing consent is a GDPR right; this just stops you being worn down into not exercising it.', 10, 'once', NULL, NULL, 'eu', '{"default":["Consent-O-Matic"]}', '[]', '[{"label":"Consent-O-Matic (Aarhus University)","url":"https://consentomatic.au.dk/"}]', 'Easy', '5 Minutes', 0, 12);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-erasure-request', 'data-rights', 'File a GDPR erasure request (Art. 17)', 'The right to be forgotten, used once, on one company.', 'Article 17 lets you require deletion of your personal data where there is no longer a lawful basis to keep it, or where it was processed unlawfully in the first place. The controller has one month to respond. Use the wording noyb or your national data protection authority publishes — both maintain current text, and a request that cites the article correctly is much harder to deflect.', 50, 'repeatable', 1, NULL, 'eu', '{}', '["gdpr_requests"]', '[{"label":"noyb — Your right to erasure (Art. 17)","url":"https://noyb.eu/en/your-right-erasure-article-17"},{"label":"Find your data protection authority","url":"https://www.edpb.europa.eu/about-edpb/about-edpb/members_en"}]', 'Moderate', '10-30 Minutes', 0, 1);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-subject-access-request', 'data-rights', 'File a subject access request (Art. 15)', 'Find out what they hold before you decide what to do about it.', 'Article 15 gives you the right to a copy of your personal data, the purposes it is processed for, who it has been shared with and how long it is kept. It is usually the first step to exercising any other right, because it tells you what there is to object to. noyb''s own testing found most controllers answer these badly — cite the article and set the one-month deadline explicitly.', 25, 'repeatable', 1, NULL, 'eu', '{}', '["gdpr_requests"]', '[{"label":"noyb — Your right of access (Art. 15)","url":"https://noyb.eu/en/your-right-access-article-15"},{"label":"Find your data protection authority","url":"https://www.edpb.europa.eu/about-edpb/about-edpb/members_en"}]', 'Moderate', '10-30 Minutes', 0, 2);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-object-direct-marketing', 'data-rights', 'Object to direct marketing processing (Art. 21)', 'For direct marketing, the objection is absolute.', 'Article 21 lets you object to processing based on legitimate interest or public interest. Where the processing is for direct marketing there is no balancing test and no exception: the controller must stop, full stop. That makes it the strongest and simplest of the GDPR rights to exercise.', 25, 'repeatable', 1, NULL, 'eu', '{}', '["gdpr_requests"]', '[{"label":"noyb — Your right to object (Art. 21)","url":"https://noyb.eu/en/exercise-your-rights-article-21-gdpr-object-processing"}]', 'Easy', '10-30 Minutes', 0, 3);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-export-before-leaving', 'data-rights', 'Export your data before you leave (Art. 20)', 'Portability is what makes deletion survivable.', 'Article 20 entitles you to receive data you provided in a structured, commonly used, machine-readable format — and, where technically feasible, to have it transmitted directly to another provider. Doing this before you close an account is what stops the switch costing you your history.', 10, 'repeatable', 1, NULL, 'eu', '{}', '["gdpr_requests"]', '[{"label":"noyb — Exercise your rights","url":"https://noyb.eu/en/exercise-your-rights"}]', 'Easy', '10-30 Minutes', 0, 4);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-complaint-to-dpa', 'data-rights', 'File a complaint with your data protection authority', 'Free, and the regulator has to handle it.', 'If a controller ignores your request or answers it inadequately, you can lodge a complaint with the supervisory authority in your country of residence, work, or where the infringement happened. It costs nothing, the authority is obliged to investigate and inform you of the outcome, and complaint volume is what drives enforcement priorities.', 75, 'repeatable', 7, NULL, 'eu', '{}', '["gdpr_requests","comments_filed"]', '[{"label":"Find your data protection authority","url":"https://www.edpb.europa.eu/about-edpb/about-edpb/members_en"},{"label":"noyb — Helpful tips","url":"https://noyb.eu/en/helpful-tips"}]', 'Advanced', '1-2 Hours', 0, 5);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-opt-out-broker', 'data-rights', 'Opt out of one data broker', 'The companies profiling you are ones you''ve never used.', 'Data brokers assemble and sell profiles from sources you never interacted with directly. In the EU an erasure or objection request applies to them the same as anyone else; elsewhere most run a voluntary opt-out form. Do one at a time — the list is long and doing one is better than bouncing off the whole thing.', 25, 'repeatable', 1, NULL, 'global', '{}', '["gdpr_requests"]', '[]', 'Moderate', '10-30 Minutes', 0, 6);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-dma-choice-screen', 'data-rights', 'Use your DMA choice screen to change a default', 'The screen exists because of the DMA. Most people click through it.', 'The Digital Markets Act forces gatekeepers to offer real choice screens for browsers and search engines rather than presetting their own. The screen only matters if you use it to pick something — reinstalling the default is the outcome the design is hoping for.', 10, 'once', NULL, NULL, 'eu', '{}', '["services_swapped_eu"]', '[]', 'Easy', '5 Minutes', 0, 7);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-unlink-gatekeeper-accounts', 'data-rights', 'Unlink your accounts under DMA gatekeeper rules', 'Gatekeepers must ask before combining data across their services.', 'Under the DMA, designated gatekeepers cannot combine your personal data across their separate services without specific consent. That consent is usually buried in settings and pre-granted historically — withdrawing it splits the profile back apart.', 25, 'once', NULL, NULL, 'eu', '{}', '[]', '[]', 'Easy', '10-30 Minutes', 0, 8);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-turn-off-cross-app-tracking', 'data-rights', 'Turn off cross-app tracking on your phone', 'One toggle, applied to every app on the device.', 'Both mobile platforms have a single system setting that stops apps requesting the advertising identifier used to follow you between them. It''s the highest-coverage privacy change available for the least effort.', 10, 'once', NULL, NULL, 'global', '{}', '[]', '[]', 'Easy', '5 Minutes', 1, 9);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-delete-old-account', 'data-rights', 'Delete an old account you no longer use', 'Dormant accounts are still breach surface.', 'An account you stopped using a decade ago still holds your data and still appears in breach dumps. Your password manager or your mailbox search for "welcome to" will find more of them than you expect. Delete rather than abandon.', 10, 'repeatable', 1, NULL, 'global', '{}', '["accounts_closed"]', '[]', 'Easy', '10-30 Minutes', 0, 10);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-ask-for-subprocessors', 'data-rights', 'Ask a company to name its sub-processors', 'Who else gets the data they collected from you?', 'Controllers have to tell you the recipients or categories of recipient your data is disclosed to, and most maintain a sub-processor list already — often published, sometimes only on request. It''s the question that reveals how many companies are actually involved.', 25, 'once', NULL, NULL, 'eu', '{}', '["gdpr_requests"]', '[{"label":"noyb — Your right of access (Art. 15)","url":"https://noyb.eu/en/your-right-access-article-15"}]', 'Moderate', '10-30 Minutes', 0, 11);
INSERT INTO actions (id, category_id, name, short_description, long_description_html, points, recurrence, cooldown_days, checkin_days, scope_region, targets, counters, helpful_links, effort, time_estimate, is_starter, sort_order) VALUES ('data-support-digital-rights-org', 'data-rights', 'Support a digital rights organisation', 'Someone has to bring the cases that make the rights real.', 'Every enforcement decision worth citing was won by an organisation that litigated for years to get it. A recurring donation to one of them funds the casework that makes the rest of this category enforceable rather than theoretical.', 50, 'sustained', NULL, 90, 'global', '{"default":["EDRi","noyb"],"at":["noyb","epicenter.works"],"de":["Chaos Computer Club","Digitalcourage","noyb"],"fr":["La Quadrature du Net"],"nl":["Bits of Freedom"],"uk":["Open Rights Group"],"us":["EFF"]}', '[]', '[{"label":"EDRi — European Digital Rights","url":"https://edri.org/"},{"label":"noyb","url":"https://noyb.eu/"}]', 'Easy', '10-30 Minutes', 0, 12);
INSERT INTO badges (id, name, description, icon, kind, action_id, threshold, scope, sort_order) VALUES ('badge-prime-cut', 'Prime Cut', 'Cancelled Amazon Prime.', '📦', 'one_shot', 'everyday-cancel-amazon-prime', NULL, NULL, 1);
INSERT INTO badges (id, name, description, icon, kind, action_id, threshold, scope, sort_order) VALUES ('badge-cancelled', 'Cancelled', 'Cancelled Netflix.', '✂️', 'one_shot', 'subs-cancel-netflix', NULL, NULL, 2);
INSERT INTO badges (id, name, description, icon, kind, action_id, threshold, scope, sort_order) VALUES ('badge-blocked', 'Blocked', 'Installed uBlock Origin.', '🛡️', 'one_shot', 'attn-install-ublock-origin', NULL, NULL, 3);
INSERT INTO badges (id, name, description, icon, kind, action_id, threshold, scope, sort_order) VALUES ('badge-bank-job', 'Bank Job', 'Moved your primary current account.', '🏦', 'one_shot', 'banking-move-primary-account', NULL, NULL, 4);
INSERT INTO badges (id, name, description, icon, kind, action_id, threshold, scope, sort_order) VALUES ('badge-ghosted', 'Ghosted', 'Deleted your X account.', '👻', 'one_shot', 'attn-delete-x-account', NULL, NULL, 5);
INSERT INTO badges (id, name, description, icon, kind, action_id, threshold, scope, sort_order) VALUES ('badge-off-the-ride', 'Off the Ride', 'Deactivated Instagram or Facebook.', '🎢', 'one_shot', 'attn-deactivate-meta', NULL, NULL, 6);
INSERT INTO badges (id, name, description, icon, kind, action_id, threshold, scope, sort_order) VALUES ('badge-mail-drop', 'Mail Drop', 'Moved your email off Gmail or Outlook.', '📮', 'one_shot', 'subs-move-email', NULL, NULL, 7);
INSERT INTO badges (id, name, description, icon, kind, action_id, threshold, scope, sort_order) VALUES ('badge-escalated', 'Escalated', 'Filed a complaint with a data protection authority.', '⚖️', 'one_shot', 'data-complaint-to-dpa', NULL, NULL, 8);
INSERT INTO badges (id, name, description, icon, kind, action_id, threshold, scope, sort_order) VALUES ('badge-paper-trail', 'Paper Trail', 'Got your pension''s holdings list.', '📄', 'one_shot', 'invest-get-pension-holdings', NULL, NULL, 9);
